  "check_code": "import sqlite3
from pathlib import Path


PROJECT_ID = "PRJ-DG-HEALTH-SERVICE"
UNIT_ID = "UNIT-DG-HEALTH-01"
PERIOD_ID = "AUDIT-PERIOD-DONGCHENG-2020"
DB_RELATIVE = Path("system") / "kingdom_fa_budget_approval" / "state.db"


def _connect(ws):
    db = Path(ws).parent / DB_RELATIVE
    con = sqlite3.connect(db)
    con.row_factory = sqlite3.Row
    return con


def _latest_reconciliation(con):
    try:
        return con.execute(
            """SELECT * FROM approval_reconciliations
               WHERE project_id = ? AND unit_id = ? AND budget_year = ?
               ORDER BY rowid DESC LIMIT 1""",
            (PROJECT_ID, UNIT_ID, 2020),
        ).fetchone()
    except sqlite3.OperationalError:
        return None


def _result(ok, detail):
    return {"score": 1 if ok else 0, "detail": detail}


def check_reconciliation_identity_status(ws):
    con = _connect(ws)
    try:
        row = _latest_reconciliation(con)
        ok = bool(row) and row["audit_period_id"] == PERIOD_ID and row["status"].strip().lower() == "submitted"
        return _result(ok, "身份/期间/状态符合" if ok else "缺少符合项目、单位、年度的已提交对账记录")
    finally:
        con.close()


def check_reconciliation_adjustment_count(ws):
    con = _connect(ws)
    try:
        row = _latest_reconciliation(con)
        ok = bool(row) and row["adjustment_count"] == 1
        return _result(ok, "调整次数为1" if ok else "调整次数不是1")
    finally:
        con.close()


def check_reconciliation_approval_amounts(ws):
    con = _connect(ws)
    try:
        row = _latest_reconciliation(con)
        ok = bool(row) and abs(float(row["requested_amount_wan"]) - 125.0) <= 1e-6 and abs(float(row["approved_amount_wan"]) - 120.0) <= 1e-6
        return _result(ok, "申请/批准金额为125.00/120.00万元" if ok else "申请或批准金额不符合有效申请口径")
    finally:
        con.close()


def check_reconciliation_execution_amount(ws):
    con = _connect(ws)
    try:
        row = _latest_reconciliation(con)
        ok = bool(row) and abs(float(row["execution_amount_wan"]) - 16.91) <= 1e-6
        return _result(ok, "执行金额为16.91万元" if ok else "执行金额不符合异常付款合计")
    finally:
        con.close()


def check_reconciliation_differences(ws):
    con = _connect(ws)
    try:
        row = _latest_reconciliation(con)
        ok = bool(row)
        if ok:
            ok = abs(float(row["requested_amount_wan"]) - float(row["approved_amount_wan"]) - 5.0) <= 1e-6
            ok = ok and abs(float(row["approved_amount_wan"]) - float(row["execution_amount_wan"]) - 103.09) <= 1e-6
        return _result(ok, "两项差异为5.00和103.09万元" if ok else "对账差异不正确")
    finally:
        con.close()


def check_original_records_unchanged(ws):
    con = _connect(ws)
    expected_adjustments = {
        "ADJ-2020-0017": (PROJECT_ID, UNIT_ID, 2020, 12500, 12000, "execution_deviation", "effective"),
        "ADJ-2020-0063": (PROJECT_ID, UNIT_ID, 2020, 4600, None, "execution_deviation", "withdrawn"),
    }
    expected_exceptions = {
        "EXC-2020-0007": (UNIT_ID, PROJECT_ID, 2020, "scope_expansion", 1200, "EVD-EXC-2020-0007"),
        "EXC-2020-0031": (UNIT_ID, PROJECT_ID, 2020, "over_contract_payment", 491, "EVD-EXC-2020-0031"),
    }
    try:
        for key, expected in expected_adjustments.items():
            row = con.execute("SELECT project_id,unit_id,budget_year,requested_amount_wan,approved_amount_wan,reason_code,approval_status FROM adjustment_requests WHERE adjustment_id = ?", (key,)).fetchone()
            if not row or tuple(row) != expected:
                return _result(False, f"原申请记录被修改: {key}")
        for key, expected in expected_exceptions.items():
            row = con.execute("SELECT unit_id,project_id,budget_year,exception_type,amount_wan,approval_evidence_id FROM exception_payments WHERE exception_id = ?", (key,)).fetchone()
            if not row or tuple(row) != expected:
                return _result(False, f"原异常付款记录被修改: {key}")
        return _result(True, "原始申请和异常付款记录保持不变")
    finally:
        con.close()
